private void collectClosure(LayoutInfo info, Set<String> visited, List<LayoutInfo> out) {
   if (!visited.add(info.name)) return;
   out.add(info);
   for (Include inc : info.includes) {
      LayoutInfo child = mLayoutInfos.get(inc.layout);
      if (child != null) collectClosure(child, visited, out);
   }
}

