private static void recordId(LayoutInfo info, String idValue, XmlContext context, Element element) {
    int slash = idValue.indexOf('/');
    if (slash == -1 || slash == idValue.length() - 1) return;
    String idName = idValue.substring(slash + 1);
    if (idName.isEmpty()) return;
    info.ids.add(new IdOccurrence(idName, context.file, context.getLocation(element)));
}

